// Phase 1: .flmd (FV-Lang Markdown) Parser
// Token 및 AST 정의

// ============================================================================
// Token Types
// ============================================================================

enum TokenType {
    // 마크다운 토큰
    Markdown,      // 일반 마크다운 텍스트
    Heading1,      // # 제목
    Heading2,      // ## 소제목
    Heading3,      // ### 세번째 제목
    Paragraph,     // 일반 단락
    ListItem,      // - 항목

    // 코드 블록
    CodeBlockStart,  // ```fvlang
    CodeBlockEnd,    // ```
    CodeLine,        // 코드 줄

    // 출력 블록
    OutputBlockStart, // ```output
    OutputBlockEnd,   // ```
    OutputLine,       // 출력 줄

    // 특수
    Blank,            // 빈 줄
    EOF               // 파일 끝
}

struct Token {
    type: TokenType,
    content: String,
    line: i32,
    column: i32
}

// ============================================================================
// AST (Abstract Syntax Tree) 정의
// ============================================================================

enum BlockType {
    MarkdownText(String),
    Heading(i32, String),     // level, content
    Paragraph(String),
    CodeBlock(String),         // FV-Lang 코드
    OutputBlock(String),       // 예상 출력
    ListBlock(Vec<String>)     // 리스트 항목들
}

struct Document {
    title: String,
    blocks: Vec<BlockType>,
    metadata: Metadata
}

struct Metadata {
    version: String,
    created: String,
    modified: String
}

// ============================================================================
// Lexer (문자열 → 토큰)
// ============================================================================

fn tokenize(content: String) -> Vec<Token> {
    let mut tokens = Vec::new()
    let lines = content.split('\n')
    let mut line_num = 1
    let mut in_code_block = false
    let mut in_output_block = false

    for line in lines {
        // 코드 블록 시작/종료
        if line.starts_with("```fvlang") {
            tokens.push(Token {
                type: TokenType::CodeBlockStart,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
            in_code_block = true
        } else if line.starts_with("```output") {
            tokens.push(Token {
                type: TokenType::OutputBlockStart,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
            in_output_block = true
        } else if line.starts_with("```") && (in_code_block || in_output_block) {
            if in_code_block {
                tokens.push(Token {
                    type: TokenType::CodeBlockEnd,
                    content: "```".to_string(),
                    line: line_num,
                    column: 0
                })
                in_code_block = false
            } else {
                tokens.push(Token {
                    type: TokenType::OutputBlockEnd,
                    content: "```".to_string(),
                    line: line_num,
                    column: 0
                })
                in_output_block = false
            }
        }
        // 코드 블록 내 줄
        else if in_code_block {
            tokens.push(Token {
                type: TokenType::CodeLine,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
        }
        // 출력 블록 내 줄
        else if in_output_block {
            tokens.push(Token {
                type: TokenType::OutputLine,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
        }
        // 마크다운 토큰
        else if line.starts_with("# ") {
            tokens.push(Token {
                type: TokenType::Heading1,
                content: line[2..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("## ") {
            tokens.push(Token {
                type: TokenType::Heading2,
                content: line[3..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("### ") {
            tokens.push(Token {
                type: TokenType::Heading3,
                content: line[4..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("- ") {
            tokens.push(Token {
                type: TokenType::ListItem,
                content: line[2..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.is_empty() {
            tokens.push(Token {
                type: TokenType::Blank,
                content: "".to_string(),
                line: line_num,
                column: 0
            })
        } else {
            tokens.push(Token {
                type: TokenType::Paragraph,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
        }

        line_num = line_num + 1
    }

    tokens.push(Token {
        type: TokenType::EOF,
        content: "".to_string(),
        line: line_num,
        column: 0
    })

    tokens
}

// ============================================================================
// Parser (토큰 → AST)
// ============================================================================

fn parse(content: String) -> Result<Document, String> {
    let tokens = tokenize(content)
    let mut blocks = Vec::new()
    let mut i = 0
    let mut title = "Untitled".to_string()

    while i < tokens.len() {
        let token = &tokens[i]

        match token.type {
            TokenType::Heading1 => {
                if i == 0 {
                    title = token.content.clone()
                }
                blocks.push(BlockType::Heading(1, token.content.clone()))
                i = i + 1
            }
            TokenType::Heading2 => {
                blocks.push(BlockType::Heading(2, token.content.clone()))
                i = i + 1
            }
            TokenType::Heading3 => {
                blocks.push(BlockType::Heading(3, token.content.clone()))
                i = i + 1
            }
            TokenType::Paragraph => {
                blocks.push(BlockType::Paragraph(token.content.clone()))
                i = i + 1
            }
            TokenType::CodeBlockStart => {
                i = i + 1
                let mut code_lines = Vec::new()
                while i < tokens.len() && tokens[i].type != TokenType::CodeBlockEnd {
                    if tokens[i].type == TokenType::CodeLine {
                        code_lines.push(tokens[i].content.clone())
                    }
                    i = i + 1
                }
                let code = code_lines.join("\n")
                blocks.push(BlockType::CodeBlock(code))
                i = i + 1  // skip closing ```
            }
            TokenType::OutputBlockStart => {
                i = i + 1
                let mut output_lines = Vec::new()
                while i < tokens.len() && tokens[i].type != TokenType::OutputBlockEnd {
                    if tokens[i].type == TokenType::OutputLine {
                        output_lines.push(tokens[i].content.clone())
                    }
                    i = i + 1
                }
                let output = output_lines.join("\n")
                blocks.push(BlockType::OutputBlock(output))
                i = i + 1  // skip closing ```
            }
            TokenType::ListItem => {
                let mut items = Vec::new()
                while i < tokens.len() && tokens[i].type == TokenType::ListItem {
                    items.push(tokens[i].content.clone())
                    i = i + 1
                }
                blocks.push(BlockType::ListBlock(items))
            }
            TokenType::Blank => {
                i = i + 1
            }
            TokenType::EOF => {
                break
            }
            _ => {
                i = i + 1
            }
        }
    }

    Ok(Document {
        title: title,
        blocks: blocks,
        metadata: Metadata {
            version: "0.1.0".to_string(),
            created: "2026-03-18".to_string(),
            modified: "2026-03-18".to_string()
        }
    })
}

// ============================================================================
// Validator (AST 검증)
// ============================================================================

fn validate(doc: Document) -> Result<Document, String> {
    // 기본 검증
    if doc.title.is_empty() {
        return Err("Document title cannot be empty".to_string())
    }

    if doc.blocks.is_empty() {
        return Err("Document must contain at least one block".to_string())
    }

    // 코드 블록 뒤에 출력 블록이 오는지 검증 (선택사항)
    let mut prev_code = false
    for block in &doc.blocks {
        match block {
            BlockType::CodeBlock(_) => prev_code = true,
            BlockType::OutputBlock(_) => prev_code = false,
            _ => {}
        }
    }

    Ok(doc)
}

// ============================================================================
// Public API
// ============================================================================

fn parse_flmd(content: String) -> Result<Document, String> {
    let doc = parse(content)?
    validate(doc)
}

fn document_to_string(doc: Document) -> String {
    let mut output = String::new()
    output.push_str(&format!("# {}\n\n", doc.title))

    for block in doc.blocks {
        match block {
            BlockType::Heading(level, content) => {
                let heading = "#".repeat(level as usize)
                output.push_str(&format!("{} {}\n\n", heading, content))
            }
            BlockType::Paragraph(content) => {
                output.push_str(&format!("{}\n\n", content))
            }
            BlockType::CodeBlock(code) => {
                output.push_str("```fvlang\n")
                output.push_str(&code)
                output.push_str("\n```\n\n")
            }
            BlockType::OutputBlock(output_content) => {
                output.push_str("```output\n")
                output.push_str(&output_content)
                output.push_str("\n```\n\n")
            }
            BlockType::ListBlock(items) => {
                for item in items {
                    output.push_str(&format!("- {}\n", item))
                }
                output.push_str("\n")
            }
            _ => {}
        }
    }

    output
}

