// Phase 1: Parser Tests
// .flmd 파싱 및 검증 테스트

// ============================================================================
// Test 1: Simple Markdown Parsing
// ============================================================================

test "parse_simple_heading" {
    let content = "# Hello World\n\nThis is a test."
    let result = parse_flmd(content)

    assert(result.is_ok())
    let doc = result.unwrap()
    assert(doc.title == "Hello World")
    assert(doc.blocks.len() > 0)
}

// ============================================================================
// Test 2: Code Block Parsing
// ============================================================================

