    }
}

fn render_document_preview(doc: Document) -> String {
    let mut output = String::new()

    // 문서 제목 렌더링
    output.push_str(&format!("<h1>{}</h1>\n", doc.title))

    // 블록별 렌더링
    for (i, block) in doc.blocks.iter().enumerate() {
        output.push_str("<div class=\"block\">\n")

        match block {
            BlockType::Heading(level, content) => {
                let tag = format!("h{}", level + 1)
                output.push_str(&format!("<{}>{}</{}>\n", tag, content, tag))
            }
            BlockType::Paragraph(content) => {
                output.push_str(&format!("<p>{}</p>\n", content))
            }
            BlockType::ListBlock(items) => {
                output.push_str("<ul>\n")
                for item in items {
                    output.push_str(&format!("<li>{}</li>\n", item))
                }
                output.push_str("</ul>\n")
            }
            BlockType::CodeBlock(code) => {
                output.push_str("<pre class=\"code-block\">\n")
                output.push_str(&format!("{}\n", code))
                output.push_str("</pre>\n")
            }
            BlockType::OutputBlock(output_content) => {
                output.push_str("<pre class=\"output-block\">\n")
                output.push_str(&format!("{}\n", output_content))
                output.push_str("</pre>\n")
            }
            _ => {}
        }

        output.push_str("</div>\n")
    }

    output
}

// ============================================================================
// Code Editor: 코드 편집 (오른쪽 패널)
// ============================================================================

struct CodeEditor {
    content: String,
    language: String,
    line_numbers: bool,
    line_count: i32
}

impl CodeEditor {
    fn new(language: String) -> CodeEditor {
        CodeEditor {
            content: String::new(),
            language: language,
            line_numbers: true,
            line_count: 1
        }
    }

    fn set_content(&mut self, content: String) {
        self.line_count = content.lines().count() as i32
        self.content = content
    }

    fn append_line(&mut self, line: String) {
        self.content.push_str(&line)
        self.content.push_str("\n")
        self.line_count = self.line_count + 1
    }

    fn get_line(&self, line_num: i32) -> Option<String> {
        let lines: Vec<&str> = self.content.lines().collect()
        if line_num >= 0 && (line_num as usize) < lines.len() {
            Some(lines[line_num as usize].to_string())
        } else {
            None
        }
    }

    fn render_with_syntax(&self) -> String {
        let mut output = String::new()

        if self.line_numbers {
            for (i, line) in self.content.lines().enumerate() {
                output.push_str(&format!("{:<4} | {}\n", i + 1, line))
            }
        } else {
            output = self.content.clone()
        }

        output
    }
}

// ============================================================================
// Result Display: 실행 결과 표시
// ============================================================================

struct ExecutionResult {
    stdout: String,
    stderr: String,
    exit_code: i32,
    execution_time: f64
}

fn render_execution_result(result: ExecutionResult) -> String {
    let mut output = String::new()

    output.push_str("<div class=\"execution-result\">\n")
    output.push_str("<h3>Execution Result</h3>\n")

    if result.exit_code == 0 {
        output.push_str("<p class=\"status success\">✓ Success</p>\n")
    } else {
        output.push_str(&format!("<p class=\"status error\">✗ Error (exit code: {})</p>\n", result.exit_code))
    }

    if !result.stdout.is_empty() {
        output.push_str("<h4>Output</h4>\n")
        output.push_str(&format!("<pre>{}</pre>\n", result.stdout))
    }

    if !result.stderr.is_empty() {
        output.push_str("<h4>Errors</h4>\n")
        output.push_str(&format!("<pre class=\"error\">{}</pre>\n", result.stderr))
    }

    output.push_str(&format!("<p class=\"timing\">Execution time: {:.3}ms</p>\n", result.execution_time))
    output.push_str("</div>\n")

    output
}

// ============================================================================
// Layout: 2-Panel Layout
// ============================================================================

struct EditorLayout {
    left_panel_width: f32,      // 퍼센트 (0.0 ~ 1.0)
    right_panel_width: f32
}

impl EditorLayout {
    fn new() -> EditorLayout {
        EditorLayout {
            left_panel_width: 0.5,
            right_panel_width: 0.5
        }
    }

    fn render_html(&self, doc: Document, code_editor: CodeEditor, result: Option<ExecutionResult>) -> String {
        let mut html = String::new()

        html.push_str("<!DOCTYPE html>\n")
        html.push_str("<html>\n")
        html.push_str("<head>\n")
        html.push_str("<title>Sovereign Workspace Editor</title>\n")
        html.push_str("<style>\n")
        html.push_str("body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', monospace; }\n")
        html.push_str(".container { display: flex; height: 100vh; }\n")
        html.push_str(".left-panel { width: 50%; padding: 20px; overflow-y: auto; background: #f5f5f5; }\n")
        html.push_str(".right-panel { width: 50%; padding: 20px; overflow-y: auto; background: #ffffff; }\n")
        html.push_str(".code-block { background: #272822; color: #f8f8f2; padding: 10px; border-radius: 4px; }\n")
        html.push_str(".output-block { background: #e8f4f8; padding: 10px; border-radius: 4px; }\n")
        html.push_str(".status { margin: 10px 0; }\n")
        html.push_str(".success { color: green; }\n")
        html.push_str(".error { color: red; }\n")
        html.push_str("</style>\n")
        html.push_str("</head>\n")
        html.push_str("<body>\n")
        html.push_str("<div class=\"container\">\n")

        // Left Panel: Document Preview
        html.push_str("<div class=\"left-panel\">\n")
        html.push_str(&render_document_preview(doc))
        html.push_str("</div>\n")

        // Right Panel: Code Editor + Results
        html.push_str("<div class=\"right-panel\">\n")
        html.push_str("<h2>Code Editor</h2>\n")
        html.push_str("<pre class=\"code-editor\">\n")
        html.push_str(&code_editor.render_with_syntax())
        html.push_str("</pre>\n")

        // Execution Results
        if let Some(exec_result) = result {
            html.push_str(&render_execution_result(exec_result))
        }

        html.push_str("</div>\n")
        html.push_str("</div>\n")
        html.push_str("</body>\n")
        html.push_str("</html>\n")

        html
    }
}

// ============================================================================
// Main Editor
// ============================================================================

struct Editor {
    state: EditorState,
    config: EditorConfig,
    layout: EditorLayout,
