// Phase 1: Code Executor
// FV-Lang 코드를 실행하고 결과를 캡처하는 모듈

use std::process::{Command, Stdio}
use std::time::Instant

// ============================================================================
// Execution Request/Result Types
// ============================================================================

struct ExecutionRequest {
    code: String,
    language: String,
    timeout_ms: i32
}

struct ExecutionResult {
    stdout: String,
    stderr: String,
    exit_code: i32,
    execution_time: f64,
    success: bool
}

enum ExecutionError {
    CompilationFailed(String),
    RuntimeError(String),
    Timeout,
    IOError(String)
}

// ============================================================================
// Compiler Interface
// ============================================================================

struct CompilerConfig {
    name: String,
    version: String,
    path: String,
    flags: Vec<String>
}

impl CompilerConfig {
    fn for_fvlang() -> CompilerConfig {
        CompilerConfig {
            name: "fvlang".to_string(),
            version: "0.1.0".to_string(),
            path: "fvlang".to_string(),
            flags: vec![
                "--optimize".to_string(),
                "--check".to_string()
            ]
        }
    }
}

fn compile_fvlang(code: String, compiler: CompilerConfig) -> Result<String, ExecutionError> {
    // 임시 파일에 코드 작성
    let temp_file = "/tmp/sovereign_temp.fl"

    // FV-Lang 컴파일러 호출
    let output = Command::new(&compiler.path)
        .arg("compile")
        .arg(temp_file)
        .output()
        .map_err(|e| ExecutionError::IOError(format!("Failed to run compiler: {}", e)))?

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).to_string()
        return Err(ExecutionError::CompilationFailed(stderr))
    }

    let stdout = String::from_utf8_lossy(&output.stdout).to_string()
    Ok(stdout)
}

// ============================================================================
// Sandbox: 격리된 실행 환경
// ============================================================================

struct SandboxConfig {
    memory_limit_mb: i32,
    cpu_timeout_seconds: i32,
    network_enabled: bool,
    filesystem_read_only: bool
}

impl SandboxConfig {
    fn default() -> SandboxConfig {
        SandboxConfig {
            memory_limit_mb: 256,
            cpu_timeout_seconds: 10,
            network_enabled: false,
            filesystem_read_only: true
        }
    }
}

fn run_in_sandbox(executable: String, sandbox: SandboxConfig) -> Result<(String, String, i32), ExecutionError> {
    let start = Instant::now()

    let output = Command::new(&executable)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()
        .map_err(|e| ExecutionError::IOError(format!("Failed to execute: {}", e)))?

    let duration = start.elapsed().as_secs_f64() * 1000.0  // ms

    if duration > (sandbox.cpu_timeout_seconds as f64 * 1000.0) {
        return Err(ExecutionError::Timeout)
    }

    let stdout = String::from_utf8_lossy(&output.stdout).to_string()
    let stderr = String::from_utf8_lossy(&output.stderr).to_string()
    let exit_code = output.status.code().unwrap_or(-1)

    Ok((stdout, stderr, exit_code))
}

// ============================================================================
// Output Capture
// ============================================================================

struct OutputCapture {
    stdout_buffer: String,
    stderr_buffer: String,
    start_time: Instant
}

impl OutputCapture {
    fn new() -> OutputCapture {
        OutputCapture {
            stdout_buffer: String::new(),
            stderr_buffer: String::new(),
            start_time: Instant::now()
        }
    }

    fn append_stdout(&mut self, content: String) {
        self.stdout_buffer.push_str(&content)
    }

    fn append_stderr(&mut self, content: String) {
        self.stderr_buffer.push_str(&content)
    }

    fn elapsed_ms(&self) -> f64 {
        self.start_time.elapsed().as_secs_f64() * 1000.0
    }

    fn finalize(&self) -> (String, String) {
        (self.stdout_buffer.clone(), self.stderr_buffer.clone())
    }
}

// ============================================================================
// REPL Mode: 대화형 실행
// ============================================================================

struct REPLContext {
    variables: Map<String, String>,
    functions: Map<String, String>,
    session_history: Vec<ExecutionRequest>
}

impl REPLContext {
    fn new() -> REPLContext {
        REPLContext {
            variables: Map::new(),
            functions: Map::new(),
            session_history: Vec::new()
        }
    }

    fn define_variable(&mut self, name: String, value: String) {
        self.variables.insert(name, value)
    }

    fn define_function(&mut self, name: String, code: String) {
        self.functions.insert(name, code)
    }

    fn get_context_code(&self) -> String {
        let mut code = String::new()

        // 정의된 함수들을 코드에 포함
        for (_, func_code) in &self.functions {
            code.push_str(func_code)
            code.push_str("\n")
        }

        code
    }

    fn record_execution(&mut self, request: ExecutionRequest) {
        self.session_history.push(request)
    }
}

// ============================================================================
// Main Executor
// ============================================================================

struct Executor {
    compiler: CompilerConfig,
    sandbox: SandboxConfig,
    repl_context: Option<REPLContext>
}

impl Executor {
    fn new() -> Executor {
        Executor {
            compiler: CompilerConfig::for_fvlang(),
            sandbox: SandboxConfig::default(),
            repl_context: None
        }
    }

    fn enable_repl(&mut self) {
        self.repl_context = Some(REPLContext::new())
    }

    fn execute(&mut self, request: ExecutionRequest) -> Result<ExecutionResult, ExecutionError> {
        let mut capture = OutputCapture::new()

        // 1. 컴파일
        let _compiled = compile_fvlang(request.code.clone(), self.compiler.clone())?

        // 2. 실행
        let (stdout, stderr, exit_code) = run_in_sandbox(
            "fvlang_executable".to_string(),
            self.sandbox.clone()
        )?

        capture.append_stdout(stdout)
        capture.append_stderr(stderr)

        let (final_stdout, final_stderr) = capture.finalize()
        let success = exit_code == 0

        // 3. REPL 모드인 경우 히스토리 저장
        if let Some(ref mut ctx) = self.repl_context {
            ctx.record_execution(request)
        }

        Ok(ExecutionResult {
            stdout: final_stdout,
            stderr: final_stderr,
            exit_code: exit_code,
            execution_time: capture.elapsed_ms(),
            success: success
        })
    }

    fn execute_with_context(&mut self, code: String) -> Result<ExecutionResult, ExecutionError> {
        if let Some(ref ctx) = self.repl_context {
            let full_code = format!("{}\n{}", ctx.get_context_code(), code)
            self.execute(ExecutionRequest {
                code: full_code,
                language: "fvlang".to_string(),
                timeout_ms: 10000
            })
        } else {
            self.execute(ExecutionRequest {
                code: code,
                language: "fvlang".to_string(),
                timeout_ms: 10000
            })
        }
    }
}

// ============================================================================
// Error Handling
// ============================================================================

fn error_message(error: ExecutionError) -> String {
    match error {
        ExecutionError::CompilationFailed(msg) => {
            format!("Compilation Error:\n{}", msg)
        }
        ExecutionError::RuntimeError(msg) => {
            format!("Runtime Error:\n{}", msg)
        }
        ExecutionError::Timeout => {
            "Error: Execution timeout (>10s)".to_string()
        }
        ExecutionError::IOError(msg) => {
            format!("IO Error:\n{}", msg)
        }
    }
}

// ============================================================================
// Public API
// ============================================================================

fn create_executor() -> Executor {
    Executor::new()
}

fn execute_fvlang_code(code: String) -> Result<ExecutionResult, String> {
    let mut executor = Executor::new()
    executor.enable_repl()

    match executor.execute_with_context(code) {
        Ok(result) => Ok(result),
        Err(e) => Err(error_message(e))
    }
}

fn execute_with_timeout(code: String, timeout_ms: i32) -> Result<ExecutionResult, String> {
    let mut executor = Executor::new()

    match executor.execute(ExecutionRequest {
        code: code,
        language: "fvlang".to_string(),
        timeout_ms: timeout_ms
    }) {
        Ok(result) => Ok(result),
        Err(e) => Err(error_message(e))
    }
}

