        ExecutionError::CompilationFailed(msg) => {
            format!("Compilation Error:\n{}", msg)
        }
        ExecutionError::RuntimeError(msg) => {
            format!("Runtime Error:\n{}", msg)
        }
        ExecutionError::Timeout => {
            "Error: Execution timeout (>10s)".to_string()
        }
        ExecutionError::IOError(msg) => {
            format!("IO Error:\n{}", msg)
        }
    }
}

// ============================================================================
// Public API
// ============================================================================

fn create_executor() -> Executor {
    Executor::new()
}

fn execute_fvlang_code(code: String) -> Result<ExecutionResult, String> {
    let mut executor = Executor::new()
    executor.enable_repl()

    match executor.execute_with_context(code) {
        Ok(result) => Ok(result),
        Err(e) => Err(error_message(e))
    }
}

fn execute_with_timeout(code: String, timeout_ms: i32) -> Result<ExecutionResult, String> {
    let mut executor = Executor::new()

    match executor.execute(ExecutionRequest {
        code: code,
        language: "fvlang".to_string(),
        timeout_ms: timeout_ms
    }) {
        Ok(result) => Ok(result),
        Err(e) => Err(error_message(e))
    }
}

