// Phase 1 Week 2: Parser Optimization
// 성능 최적화된 .flmd 파서 (캐싱 + 병렬 처리 준비)

use std::collections::HashMap

// ============================================================================
// Cache Structure for Performance
// ============================================================================

struct ParserCache {
    parsed_documents: HashMap<String, Document>,
    token_cache: HashMap<String, Vec<Token>>,
    cache_hits: i32,
    cache_misses: i32
}

impl ParserCache {
    fn new() -> ParserCache {
        ParserCache {
            parsed_documents: HashMap::new(),
            token_cache: HashMap::new(),
            cache_hits: 0,
            cache_misses: 0
        }
    }

    fn get_cached_document(&mut self, file_hash: String) -> Option<Document> {
        if let Some(doc) = self.parsed_documents.get(&file_hash) {
            self.cache_hits = self.cache_hits + 1
            Some(doc.clone())
        } else {
            self.cache_misses = self.cache_misses + 1
            None
        }
    }

    fn cache_document(&mut self, file_hash: String, doc: Document) {
        self.parsed_documents.insert(file_hash, doc)
    }

    fn get_cache_stats(&self) -> (i32, i32, f32) {
        let total = self.cache_hits + self.cache_misses
        let hit_rate = if total > 0 {
            (self.cache_hits as f32) / (total as f32) * 100.0
        } else {
            0.0
        }
        (self.cache_hits, self.cache_misses, hit_rate)
    }
}

// ============================================================================
// Optimized Tokenizer (한 번의 패스로 처리)
// ============================================================================

struct TokenStream {
    tokens: Vec<Token>,
    position: usize
}

impl TokenStream {
    fn new() -> TokenStream {
        TokenStream {
            tokens: Vec::new(),
            position: 0
        }
    }

    fn add_token(&mut self, token: Token) {
        self.tokens.push(token)
    }

    fn peek(&self) -> Option<&Token> {
        if self.position < self.tokens.len() {
            Some(&self.tokens[self.position])
        } else {
            None
        }
    }

    fn next(&mut self) -> Option<Token> {
        if self.position < self.tokens.len() {
            let token = self.tokens[self.position].clone()
            self.position = self.position + 1
            Some(token)
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(token) = self.peek() {
            if matches!(token.type, TokenType::Blank) {
                self.next()
            } else {
                break
            }
        }
    }
}

// 최적화된 토큰화 (단일 패스)
fn tokenize_optimized(content: String) -> TokenStream {
    let mut stream = TokenStream::new()
    let lines: Vec<&str> = content.lines().collect()
    let mut line_num = 1
    let mut in_code_block = false
    let mut in_output_block = false

    for (idx, line) in lines.iter().enumerate() {
        // 블록 상태 관리
        if line.starts_with("```fvlang") {
            stream.add_token(Token {
                type: TokenType::CodeBlockStart,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
            in_code_block = true
        } else if line.starts_with("```output") {
            stream.add_token(Token {
                type: TokenType::OutputBlockStart,
                content: line.to_string(),
                line: line_num,
                column: 0
            })
            in_output_block = true
        } else if line.starts_with("```") && (in_code_block || in_output_block) {
            stream.add_token(Token {
                type: if in_code_block { TokenType::CodeBlockEnd } else { TokenType::OutputBlockEnd },
                content: "```".to_string(),
                line: line_num,
                column: 0
            })
            in_code_block = false
            in_output_block = false
        }
        // 마크다운 토큰 식별 (인라인 처리)
        else if line.starts_with("# ") && !in_code_block && !in_output_block {
            stream.add_token(Token {
                type: TokenType::Heading1,
                content: line[2..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("## ") && !in_code_block && !in_output_block {
            stream.add_token(Token {
                type: TokenType::Heading2,
                content: line[3..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("### ") && !in_code_block && !in_output_block {
            stream.add_token(Token {
                type: TokenType::Heading3,
                content: line[4..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.starts_with("- ") && !in_code_block && !in_output_block {
            stream.add_token(Token {
                type: TokenType::ListItem,
                content: line[2..].to_string(),
                line: line_num,
                column: 0
            })
        } else if line.is_empty() {
            stream.add_token(Token {
                type: TokenType::Blank,
                content: "".to_string(),
                line: line_num,
                column: 0
            })
        } else {
            // 블록 내 줄 처리
            if in_code_block {
                stream.add_token(Token {
                    type: TokenType::CodeLine,
                    content: line.to_string(),
                    line: line_num,
                    column: 0
                })
            } else if in_output_block {
                stream.add_token(Token {
                    type: TokenType::OutputLine,
                    content: line.to_string(),
                    line: line_num,
                    column: 0
                })
            } else {
                stream.add_token(Token {
                    type: TokenType::Paragraph,
                    content: line.to_string(),
                    line: line_num,
                    column: 0
                })
            }
        }

        line_num = line_num + 1
    }

    stream.add_token(Token {
        type: TokenType::EOF,
        content: "".to_string(),
        line: line_num,
        column: 0
    })

    stream
}

// ============================================================================
