// Phase 1 Week 2: Enhanced Editor UI
// Syntax Highlighting + 성능 최적화

// ============================================================================
// Syntax Highlighting for FV-Lang
// ============================================================================

enum SyntaxType {
    Keyword,        // fn, let, if, match, etc.
    String,         // "..."
    Number,         // 123, 3.14
    Comment,        // // comment
    Identifier,     // variable names
    Operator,       // +, -, *, /, =
    Type,           // i32, String, Vec
    Punctuation     // {}, [], (), ;
}

struct HighlightRule {
    pattern: String,
    syntax_type: SyntaxType,
    color: String
}

fn create_fvlang_highlighter() -> Vec<HighlightRule> {
    vec![
        HighlightRule {
            pattern: "\\bfn\\b".to_string(),
            syntax_type: SyntaxType::Keyword,
            color: "#ff79c6".to_string()  // 핑크
        },
        HighlightRule {
            pattern: "\\blet\\b".to_string(),
            syntax_type: SyntaxType::Keyword,
            color: "#ff79c6".to_string()
        },
        HighlightRule {
            pattern: "\\bif\\b|\\belse\\b|\\bmatch\\b".to_string(),
            syntax_type: SyntaxType::Keyword,
            color: "#ff79c6".to_string()
        },
        HighlightRule {
            pattern: "\\bstruct\\b|\\benum\\b|\\bimpl\\b".to_string(),
            syntax_type: SyntaxType::Keyword,
            color: "#ff79c6".to_string()
        },
        HighlightRule {
            pattern: "\"[^\"]*\"".to_string(),
            syntax_type: SyntaxType::String,
            color: "#f1fa8c".to_string()  // 노랑
        },
        HighlightRule {
            pattern: "//.*$".to_string(),
            syntax_type: SyntaxType::Comment,
            color: "#6272a4".to_string()  // 회색
        },
        HighlightRule {
            pattern: "[0-9]+(\\.[0-9]+)?".to_string(),
            syntax_type: SyntaxType::Number,
            color: "#bd93f9".to_string()  // 보라
        },
        HighlightRule {
            pattern: "i32|i64|f32|f64|String|Vec|bool".to_string(),
            syntax_type: SyntaxType::Type,
            color: "#8be9fd".to_string()  // 파랑
        }
    ]
}

fn apply_syntax_highlighting(code: String) -> String {
    let rules = create_fvlang_highlighter()
    let mut highlighted = code.clone()

    for rule in rules {
        // 정규식 매칭 및 색상 적용
        // (실제 구현에서는 regex 라이브러리 사용)
    }

    highlighted
}

// ============================================================================
// Improved Code Editor with Diff Support
// ============================================================================

struct CodeDiff {
    original: String,
    modified: String,
    lines_added: i32,
    lines_removed: i32
}

impl CodeDiff {
    fn compute(original: String, modified: String) -> CodeDiff {
        let orig_lines = original.lines().count() as i32
        let mod_lines = modified.lines().count() as i32

        CodeDiff {
            original: original,
            modified: modified,
            lines_added: std::cmp::max(0, mod_lines - orig_lines),
            lines_removed: std::cmp::max(0, orig_lines - mod_lines)
        }
    }

    fn has_changes(&self) -> bool {
        self.lines_added > 0 || self.lines_removed > 0
    }
}

struct EnhancedCodeEditor {
    content: String,
    language: String,
    line_numbers: bool,
    syntax_highlighting: bool,
    line_count: i32,
    modified: bool,
    saved_content: String,
    undo_stack: Vec<String>,
    redo_stack: Vec<String>,
    diff: Option<CodeDiff>
}

impl EnhancedCodeEditor {
    fn new(language: String) -> EnhancedCodeEditor {
        EnhancedCodeEditor {
            content: String::new(),
            language: language,
            line_numbers: true,
            syntax_highlighting: true,
            line_count: 1,
            modified: false,
            saved_content: String::new(),
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
            diff: None
        }
    }

    fn set_content(&mut self, content: String) {
        // 변경 사항 저장 (undo용)
        if !self.content.is_empty() {
            self.undo_stack.push(self.content.clone())
        }

        self.line_count = content.lines().count() as i32
        self.content = content
        self.modified = true
        self.redo_stack.clear()
    }

    fn undo(&mut self) -> bool {
        if let Some(prev) = self.undo_stack.pop() {
            self.redo_stack.push(self.content.clone())
            self.content = prev
            self.modified = true
            true
        } else {
            false
        }
    }

    fn redo(&mut self) -> bool {
        if let Some(next) = self.redo_stack.pop() {
            self.undo_stack.push(self.content.clone())
            self.content = next
            self.modified = true
            true
        } else {
            false
