                output.push_str("\n")
            }
        } else {
            for (i, line) in self.content.lines().enumerate() {
                if self.line_numbers {
                    output.push_str(&format!("{:<4} │ ", i + 1))
                }
                output.push_str(line)
                output.push_str("\n")
            }
        }

        output
    }

    fn get_stats(&self) -> (i32, i32, bool, i32, i32) {
        let word_count = self.content.split_whitespace().count() as i32
        let char_count = self.content.len() as i32
        (self.line_count, word_count, self.modified, char_count, self.undo_stack.len() as i32)
    }
}

