                html.push_str("<span style=\"color: #50fa7b;\">✓ Success</span>\n")
            } else {
                html.push_str(&format!("<span style=\"color: #ff79c6;\">✗ Error (code: {})</span>\n", result.exit_code))
            }
            html.push_str("<pre>")
            html.push_str(&result.stdout)
            if !result.stderr.is_empty() {
                html.push_str("STDERR:\n")
                html.push_str(&result.stderr)
            }
            html.push_str("</pre>\n")
        } else {
            html.push_str("<span style=\"color: #888;\">Ready to execute...</span>\n")
        }
        html.push_str("</div>\n")

        html.push_str("</div>\n</div>\n")

        // Status Bar
        let (lines, words, modified, chars, undo_count) = editor.get_stats()
        html.push_str("<div class=\"status-bar\">\n")
        html.push_str(&format!("<div class=\"status-item\"><span>Ln {}, Col 0</span><span>Words: {}</span><span>Chars: {}</span></div>\n", lines, words, chars))
        html.push_str(&format!("<div class=\"status-item\"><span>{}</span><span>Undo: {} steps</span></div>\n",
            if modified { "Modified" } else { "Saved" },
            undo_count))
        html.push_str("</div>\n")

        html.push_str("</body>\n</html>\n")

        html
    }
}

// ============================================================================
// Enhanced Editor Main Class
// ============================================================================

struct EnhancedEditor {
    state: EditorState,
    code_editor: EnhancedCodeEditor,
    layout: EnhancedEditorLayout,
    auto_save_enabled: bool,
    auto_save_interval: i32  // seconds
}

impl EnhancedEditor {
    fn new() -> EnhancedEditor {
        EnhancedEditor {
            state: EditorState {
                document: Document {
                    title: "Untitled".to_string(),
                    blocks: Vec::new(),
                    metadata: Metadata {
                        version: "0.2.0".to_string(),
                        created: "2026-03-18".to_string(),
                        modified: "2026-03-25".to_string()
                    }
                },
                current_file: "untitled.flmd".to_string(),
                is_modified: false,
                selected_block: None,
                cursor_position: (0, 0)
            },
            code_editor: EnhancedCodeEditor::new("fvlang".to_string()),
            layout: EnhancedEditorLayout::new(),
            auto_save_enabled: true,
            auto_save_interval: 60
        }
    }

    fn load_document(&mut self, content: String) -> Result<(), String> {
        let doc = parse_flmd_optimized(content)?
        self.state.document = doc
        self.state.is_modified = false
        Ok(())
    }

    fn render_html(&self) -> String {
        self.layout.render_html(
            self.state.document.clone(),
            &self.code_editor,
            None
        )
    }

    fn toggle_syntax_highlighting(&mut self) {
        self.code_editor.syntax_highlighting = !self.code_editor.syntax_highlighting
    }

    fn set_theme(&mut self, theme: String) {
        self.layout.with_theme(theme)
    }
}

