// 전체 통합 검증 및 최종 테스트

// ============================================================================
// Test 1: Application Initialization
// ============================================================================

test "application_initializes_successfully" {
    let mut app = EditorApplication::new("test_session".to_string())

    assert(app.is_running == false)
    assert(!app.config.theme.is_empty())
    assert(app.config.auto_save == true)
}

// ============================================================================
// Test 2: Application Startup
// ============================================================================

test "application_starts_correctly" {
    let mut app = EditorApplication::new("test_session".to_string())

    let start_result = app.start()
    assert(start_result.is_ok())
    assert(app.is_running == true)
}

// ============================================================================
// Test 3: Document Loading
// ============================================================================

test "document_loads_into_editor" {
    let mut app = EditorApplication::new("test_session".to_string())
    app.start().ok()

    let content = "# Test Document\n\nContent here"
    let load_result = app.open_file("test.flmd".to_string(), content)

    assert(load_result.is_ok())
    assert(app.workflow.editor.state.current_file == "test.flmd")
}

// ============================================================================
// Test 4: HTML Rendering
// ============================================================================

test "editor_renders_html_output" {
    let mut app = EditorApplication::new("test_session".to_string())
    app.start().ok()

    let content = "# Test\n\nContent"
    app.open_file("test.flmd".to_string(), content).ok()

    let html = app.get_html()

    assert(html.contains("<!DOCTYPE html>"))
    assert(html.contains("Test"))
    assert(!html.is_empty())
}

// ============================================================================
// Test 5: Code Execution Integration
// ============================================================================

test "code_execution_integrated_with_editor" {
    let mut app = EditorApplication::new("test_session".to_string())
    app.start().ok()

    let content = "# Program\n\n```fvlang\nfn main() {\n    let x = 42\n    print(x)\n}\n```"
    app.open_file("program.flmd".to_string(), content).ok()

    // Code execution would be tested here
