// Test 7: Theme Switching
// ============================================================================

test "theme_switching_works" {
    let mut app = EditorApplication::new("test_session".to_string())
    app.start().ok()

    app.apply_theme("light".to_string())
    assert(app.config.theme == "light")

    app.apply_theme("dracula".to_string())
    assert(app.config.theme == "dracula")
